function icon(name){const paths={back:'<path d="M19 12H5M12 19l-7-7 7-7"/>',next:'<path d="M5 12h14m-7-7 7 7-7 7"/>',launch:'<path d="M5 19 19 5M9 5h10v10"/>',spark:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Z"/>',home:'<path d="m3 10 9-7 9 7M5 9v11h14V9m-9 11v-6h4v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>'};return `<svg class="ava-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.next}</svg>`;}
const money = value => Number.isFinite(Number(value)) ? new Intl.NumberFormat("zh-HK", { maximumFractionDigits: 0 }).format(Math.round(Number(value))) : "—";
const usd = value => `US$${money(value)}`;
const hkd = value => `HK$${money(value)}`;
